local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool


local IdolLive3D_Utils = import('Game.IdolLive3D.IdolLive3D_Utils')

---@type IdolLive3D_States
local IdolLive3D_States = import('Game.IdolLive3D.IdolLive3D_States')
local IdleType = IdolLive3D_States.IdleType


local IdolLive3D_Input = import("Game.IdolLive3D.IdolLive3D_Input")

local IdolLive3D_FullScreenFX = import("Game.IdolLive3D.Interactive.IdolLive3D_FullScreenFX")

---@type Live3D_UIKey
local Live3D_UIKey = import('Game.IdolLive3D.Interactive.Customs.Live3D_UIKey')

local gameUtils = GameUtils

-- ========================================================





-- ========================================================

---@param idolLive3D_SuperTimeLineState_ table
function SuperTimeline_13600850_100Enter:__init( idolLive3D_SuperTimeLineState_ )
    
    self.idolLive3D_SuperTimeLineState = idolLive3D_SuperTimeLineState_
    self.lastClipId = nil -- 最后一次登记的 clipId

    ---
    local allResources = self.idolLive3D_SuperTimeLineState.idolLive3D_InteractiveManager.allResources
    self.fullScreenFXEnv = allResources.fullScreenFXEnvs["base"]
    assert( isNotNull(self.fullScreenFXEnv) )


    self.tips = {
        duration = 4,
        lastStartTime = 0,
    }

    Events.Broadcast(IdolLive3D_States.EventSetUICustomGray, Live3D_UIKey.switchPanel, true, true) -- 入场直接置灰 switchBtn
    Events.Broadcast(IdolLive3D_States.EventSetUIBtnCustomClickFunc, Live3D_UIKey.switchPanel, function( uiSwitchBtnEnv_ )
        --- 防止重复触发:
        if (Time.time - self.tips.lastStartTime) > (self.tips.duration * 0.5 ) then 
            self.tips.lastStartTime = Time.time
            gameUtils.Toast(localize("触发隐藏动作后，进入后续亲密互动环节"), self.tips.duration ) -- 飘字
        end
    end)


    self.isFXPlayed = false
end




-- 需手动调用 Delete()
function SuperTimeline_13600850_100Enter:__delete()

    IdolLive3D_Utils.StopCoroutine(self.co_1)
    self.co_1 = nil

    IdolLive3D_Utils.StopCoroutine(self.co_2)
    self.co_2 = nil
    ---
    self.fullScreenFXEnv:Delete()
end



-- ---@param clipJson_ table @ c# class SuperTimelineClip 内数据
-- ---@param timelineStateEnv_ table
function SuperTimeline_13600850_100Enter:SelfUpdate( clipJson_, timelineStateEnv_ ) 


    local clipId = tostring(clipJson_.clipId)
    local isFirstFrame = (clipId ~= self.lastClipId)
    self.lastClipId = clipId
    
    local endTime = timelineStateEnv_.play.duration - 0.5

    if self.isFXPlayed ~= true and timelineStateEnv_.play.playTime > endTime  then 
        self.isFXPlayed = true 

        IdolLive3D_Utils.StopCoroutine(self.co_1)
        self.co_1 = cs_coroutine.start(function()            
            cs_coroutine.yield_return( self.fullScreenFXEnv:FadeIn() ) --- 全屏特效 淡入
        end) 
    end 


    --- None,Hold 模式就是唯一一遍尾后帧,
    if timelineStateEnv_.play.loopInteger > 0 then 
        self:EndPLay( clipJson_, timelineStateEnv_ )
    end 
end



-- 每次重播 superTimeline 的入场cb:
function SuperTimeline_13600850_100Enter:StartPlay() 
    self.isFXPlayed = false 
end 




---@param clipJson_ table @ c# class SuperTimelineClip 内数据
---@param timelineStateEnv_ table
function SuperTimeline_13600850_100Enter:EndPLay( clipJson_, timelineStateEnv_ ) 
    --printError("EndPLay")

    local idolLive3D_InteractiveManager = self.idolLive3D_SuperTimeLineState.idolLive3D_InteractiveManager
    local clipId = tostring(clipJson_.clipId)

    self.idolLive3D_SuperTimeLineState.isPlaying = false

    IdolLive3D_Utils.StopCoroutine(self.co_2)
    self.co_2 = cs_coroutine.start(function()


        cs_coroutine.yield_return( self.fullScreenFXEnv:WaitTargetState( IdolLive3D_States.FullScreenFXState.Show ) )
        self.idolLive3D_SuperTimeLineState:EndPLay()
        cs_coroutine.yield_return( self.fullScreenFXEnv:FadeOut() ) -- 全屏特效 淡出        
    end)
end




return SuperTimeline_13600850_100Enter
